input.command:
set -e; B=/workspace/.eval/tmp; mkdir -p "$B"; M=$(mktemp -d "$B/merged.XXXXXX"); echo "$M" > /tmp/merged2.path; cp -rL /workspace/.claude "$M/.claude" 2>/dev/null || cp -r /workspace/.claude "$M/.claude"; cp /workspace/.loa.config.yaml "$M/"; (cd /workspace/pr/head && find . -type f -print0 | while IFS= read -r -d '' f; do mkdir -p "$M/$(dirname "$f")"; cp -p "$f" "$M/$f"; done); chmod +x "$M"/evals/harness/*.sh "$M"/tools/*.sh "$M"/evals/tests/fixtures/*.sh "$M"/evals/tests/fixtures/ablation/*.sh "$M"/evals/tests/fixtures/ablation-runs/regen.sh; cd "$M"; git init -q; git -c user.name=t -c user.email=t@t -c core.hooksPath=/dev/null -c commit.gpgsign=false add -A >/dev/null 2>&1; git -c user.name=t -c user.email=t@t -c core.hooksPath=/dev/null -c commit.gpgsign=false commit -qm merged; "$M/evals/harness/spend.sh" --help >/dev/null 2>&1; echo "direct exec rc=$? (2 expected from --help usage)"; 
# patched copy: jq-1.6-safe object keys
P=$(mktemp -d "$B/patched.XXXXXX"); echo "$P" > /tmp/patched.path; cp -a "$M/." "$P/"; 
sed -i -e 's/{label: \$label,/{"label": \$label,/' -e 's/, label: \$label,/, "label": $label,/' -e 's/label: \$n}/"label": $n}/' -e 's/label: ("FIX"/"label": ("FIX"/' "$P/evals/harness/pipeline-run.sh"; sed -i -e 's/{name, label, session_id/{name, "label": .label, session_id/' "$P/evals/harness/ablation-row.sh"; diff "$M/evals/harness/pipeline-run.sh" "$P/evals/harness/pipeline-run.sh" | grep '^[<>]'; diff "$M/evals/harness/ablation-row.sh" "$P/evals/harness/ablation-row.sh" | grep '^[<>]'; grep -c 'label:' "$P/evals/harness/pipeline-run.sh"
